#include "rigid.hpp"
#include <iostream>
#include <fstream>
#include <iomanip>
using namespace rigid;
int main(){std::ofstream out("hidden_modes.csv");out<<std::setprecision(16)<<"case,source,h,normal_norm,predicted_doubling_limit,velocity_reflection_error,doubling_gap,energy_error,residual,ok\n";
for(auto c:cases()){if(c.name!="double_moderate"&&c.name!="triple_moderate")continue;Scale q=scales(c.model,c.initial);for(std::string source:{"genuine_previous_step","injected_normal"}){State s;if(source=="genuine_previous_step")s=dg_full(c.model,c.initial,.05,q).s;else{s=c.initial;V inv=masses(c.model).cwiseInverse();s.v+=.01*inv.cwiseProduct(gradient(c.model,s.x).transpose()*V::Ones(c.model.count));}Mat g=gradient(c.model,s.x);V inv=masses(c.model).cwiseInverse(),normal=inv.cwiseProduct(g.transpose()*(g*inv.asDiagonal()*g.transpose()).ldlt().solve(g*s.v)),reflect=s.v-2*normal;for(double h:{.01,.001,.0001,.00001,.000001}){Result a=dg_full(c.model,s,h,q),b=dg_full(c.model,s,h/2,q),d=dg_full(c.model,b.s,h/2,q);out<<c.name<<","<<source<<","<<h<<","<<normal.norm()/q.v<<","<<2*normal.norm()/q.v<<","<<(a.s.v-reflect).norm()/q.v<<","<<(encode(a.s,q)-encode(d.s,q)).norm()<<","<<std::abs(energy(c.model,a.s)-energy(c.model,s))/q.e<<","<<a.residual<<","<<(a.ok&&b.ok&&d.ok)<<"\n";}}}
std::ofstream validation("objective_validation.csv");validation<<std::setprecision(16)<<"case,variant,column,gradient_error,hessian_error,row_gradient_error,row_hessian_error\n";double worst=0;int columns=0;
for(auto c:cases()){if(c.name!="double_moderate"&&c.name!="triple_moderate")continue;Scale q=scales(c.model,c.initial);for(auto v:objectives2::variants()){if(v.id!="quarter_b1"&&v.id!="midpotential_b1"&&v.id!="ls_dg_E"&&v.id!="projection_verlet_E")continue;objectives2::Objective p(c.model,c.initial,1./30,v,q.e);p.target=rattle(c.model,c.initial,1./30,q).s;p.aold=acceleration(c.model,c.initial);V z=p.initial();for(int j=0;j<z.size();++j)z[j]+=.001*std::sin(1+j);auto e=p.evaluate(z);for(int j=0;j<z.size();++j){double eps=1e-5;V a=z,b=z;a[j]+=eps;b[j]-=eps;auto ea=p.evaluate(a),eb=p.evaluate(b);double eg=std::abs(e.objective.g[j]-(ea.objective.a-eb.objective.a)/(2*eps))/(1+std::abs(e.objective.g[j])),eh=(e.objective.H.col(j)-(ea.objective.g-eb.objective.g)/(2*eps)).norm()/(1+e.objective.H.col(j).norm()),rg=0,rh=0;for(int k=0;k<int(e.rows.size());++k){const auto&r=e.rows[k].value;const auto&u=ea.rows[k].value;const auto&w=eb.rows[k].value;rg=std::max(rg,std::abs(r.g[j]-(u.a-w.a)/(2*eps))/(1+std::abs(r.g[j])));rh=std::max(rh,(r.H.col(j)-(u.g-w.g)/(2*eps)).norm()/(1+r.H.col(j).norm()));}worst=std::max({worst,eg,eh,rg,rh});validation<<c.name<<","<<v.id<<","<<j<<","<<eg<<","<<eh<<","<<rg<<","<<rh<<"\n";++columns;}}}
std::cout<<"objective derivative columns="<<columns<<" worst scaled discrepancy="<<worst<<"\n";return worst<1e-6?0:1;}
